<?php
declare(strict_types=1);
require_once __DIR__.'/../config/bootstrap.php';
require_once __DIR__.'/../config/business.php';
$user=require_login($pdo);$userId=(int)$user['id'];$pageTitle='Händler-Dashboard';$error='';$success='';$report=null;
$profile=business_dealer_profile($pdo,$userId,false);
$values=$profile?:['company_name'=>'','address_text'=>'','country_code'=>$user['country_code']??'DE','contact_email'=>'','website'=>'','legal_notice'=>''];
if(isset($_GET['banner_image'])){
    $id=is_string($_GET['banner_image'])?filter_var($_GET['banner_image'],FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]):false;
    if(!$id)abort_request(404,'Banner nicht gefunden.');$q=$pdo->prepare('SELECT storage_key FROM market_campaigns WHERE id=? AND user_id=?');$q->execute([$id,$userId]);$key=$q->fetchColumn();if(!is_string($key))abort_request(404,'Banner nicht gefunden.');business_output_banner($key,true);
}
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
    require_csrf();
    try{
        $action=post_string('action',24);
        if($action==='profile'){
            foreach(array_keys($values) as $key)if(isset($_POST[$key])&&is_string($_POST[$key]))$values[$key]=$_POST[$key];
            business_save_dealer($pdo,$userId,$_POST);$success='Deine Geschäftsinformationen wurden zur Prüfung gespeichert.';$profile=business_dealer_profile($pdo,$userId,false);
        }elseif($action==='campaign'){
            business_create_campaign($pdo,$userId,$_POST,$_FILES['banner']??[]);$success='Dein Banner wurde gespeichert und wartet auf die inhaltliche Prüfung.';
        }elseif($action==='bulk'){
            $ids=$_POST['listing_ids']??null;if(!is_array($ids))throw new InvalidArgumentException('Bitte eigene Inserate auswählen.');
            $count=business_bulk_transition($pdo,$userId,$ids,post_string('transition',20));$success=$count.' eigene Inserate wurden atomar geändert.';
        }elseif($action==='import'){
            $report=business_import_csv($pdo,$userId,$_FILES['csv']??[],post_string('accept_rules')==='1');$success=$report['created'].' Inserate angelegt, '.$report['duplicates'].' exakte Dubletten übersprungen.';
        }elseif($action==='export'){
            $raw=post_string('after_id',20);if($raw!==''&&!ctype_digit($raw))throw new InvalidArgumentException('Ungültige Startkennung.');$after=(int)$raw;
            $q=$pdo->prepare('SELECT l.id,l.title,l.description,c.slug,l.type,l.price_cents,l.buyout_cents,l.country_code,l.zip,l.city,l.condition_label,l.pickup,l.shipping,l.status FROM market_listings l JOIN market_categories c ON c.id=l.category_id WHERE l.seller_id=? AND l.id>? ORDER BY l.id LIMIT 1000');$q->execute([$userId,$after]);
            header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="gunindex-angebote-ab-'.$after.'.csv"');header('Cache-Control: no-store');
            $stream=fopen('php://output','wb');fwrite($stream,"\xEF\xBB\xBF");fputcsv($stream,['id','title','description','category_slug','type','price','buyout_price','country_code','zip','city','condition_label','pickup','shipping','status'],',','"','');
            while($row=$q->fetch()){$row['price_cents']=intdiv((int)$row['price_cents'],100).'.'.str_pad((string)((int)$row['price_cents']%100),2,'0',STR_PAD_LEFT);$row['buyout_cents']=$row['buyout_cents']===null?'':intdiv((int)$row['buyout_cents'],100).'.'.str_pad((string)((int)$row['buyout_cents']%100),2,'0',STR_PAD_LEFT);fputcsv($stream,array_map('business_csv_cell',array_values($row)),',','"','');}fclose($stream);exit;
        }else throw new InvalidArgumentException('Ungültige Aktion.');
    }catch(InvalidArgumentException|DomainException|MarketAccessException|MarketConflictException $exception){http_response_code(422);$error=$exception->getMessage();}
    catch(Throwable){http_response_code(503);$error='Der Vorgang konnte gerade nicht bestätigt werden. Bitte erneut versuchen; technische Details werden nicht öffentlich ausgegeben.';}
}
$country=business_country($values['country_code']??'DE');$countries=function_exists('geo_countries')?geo_countries():['DE'=>'Deutschland'];$categories=catalog_categories($pdo,true);
$q=$pdo->prepare('SELECT status,COUNT(*) AS count FROM market_listings WHERE seller_id=? GROUP BY status');$q->execute([$userId]);$listingStats=array_column($q->fetchAll(),'count','status');
$q=$pdo->prepare('SELECT COUNT(*) FROM market_watchlist w JOIN market_listings l ON l.id=w.listing_id WHERE l.seller_id=?');$q->execute([$userId]);$watchCount=(int)$q->fetchColumn();
$q=$pdo->prepare('SELECT COUNT(*) FROM market_bids b JOIN market_listings l ON l.id=b.listing_id WHERE l.seller_id=? AND b.event_type=\'bid\'');$q->execute([$userId]);$bidCount=(int)$q->fetchColumn();
$q=$pdo->prepare('SELECT COUNT(DISTINCT CONCAT(m.listing_id,\':\',m.sender_id)) FROM market_messages m JOIN market_listings l ON l.id=m.listing_id WHERE l.seller_id=? AND m.receiver_id=? AND m.sender_id<>?');$q->execute([$userId,$userId,$userId]);$contacts=(int)$q->fetchColumn();
$q=$pdo->prepare("SELECT COALESCE(SUM(gross_cents),0) FROM market_invoices WHERE user_id=? AND status='paid'");$q->execute([$userId]);$paid=(int)$q->fetchColumn();
$page=filter_var($_GET['page']??'1',FILTER_VALIDATE_INT,['options'=>['min_range'=>1,'max_range'=>100000]])?:1;$total=array_sum(array_map('intval',$listingStats));$page=min($page,max(1,(int)ceil($total/25)));
$q=$pdo->prepare('SELECT l.*,(SELECT COUNT(*) FROM market_proxy_bids b WHERE b.listing_id=l.id) AS has_bids FROM market_listings l WHERE seller_id=? ORDER BY l.id DESC LIMIT 25 OFFSET ?');$q->bindValue(1,$userId,PDO::PARAM_INT);$q->bindValue(2,($page-1)*25,PDO::PARAM_INT);$q->execute();$listings=$q->fetchAll();
$q=$pdo->prepare('SELECT c.*,COALESCE((SELECT SUM(s.impressions) FROM market_ad_daily_stats s WHERE s.campaign_id=c.id),0) AS impressions,COALESCE((SELECT SUM(s.clicks) FROM market_ad_daily_stats s WHERE s.campaign_id=c.id),0) AS clicks FROM market_campaigns c WHERE c.user_id=? ORDER BY c.id DESC LIMIT 100');$q->execute([$userId]);$campaigns=$q->fetchAll();
include __DIR__.'/../includes/header.php';
?>
<main class="container"><div class="page-heading"><p class="eyebrow">Dein Unternehmen im Überblick</p><h1><?=h(business_label('Händler-Dashboard'))?>.</h1><p>Geschäftsangaben, Angebote, Werbung und tatsächliche Kennzahlen.</p><a class="button" href="/user/promotions.php"><?=h(business_label('Premiumplätze & Händlerwerbung'))?></a></div>
<?php if($error!==''):?><p class="notice error" role="alert"><?=h($error)?></p><?php endif;?><?php if($success!==''):?><p class="notice success" role="status"><?=h($success)?></p><?php endif;?>
<div class="stats-grid"><article class="panel"><strong><?=(int)($listingStats['active']??0)?></strong><p>Aktive Angebote</p></article><article class="panel"><strong><?=$watchCount?></strong><p>Merkliste-Einträge</p></article><article class="panel"><strong><?=$contacts?></strong><p>Kontaktunterhaltungen</p></article><article class="panel"><strong><?=$bidCount?></strong><p>Öffentliche Gebotsereignisse</p></article><article class="panel"><strong><?=h(money_eur($paid))?></strong><p>Bestätigte Plattformzahlungen</p></article></div>
<section class="panel"><h2>Öffentliches Händlerprofil</h2><p>Veröffentlicht werden nur die hier ausdrücklich eingetragenen Geschäftsinformationen. Deine privaten Kontodaten werden nicht automatisch übernommen. Eine Inhaltsfreigabe ersetzt keine behördliche Erlaubnis oder Identitätsbestätigung.</p><?php if($profile):?><p>Status: <?=h(business_state_label($profile['status']))?><?php if($profile['moderation_reason']):?> · <?=h($profile['moderation_reason'])?><?php endif;?></p><?php endif;?>
<form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="profile"><label class="field">Firma<input name="company_name" minlength="2" maxlength="150" value="<?=h($values['company_name'])?>" required></label><label class="field">Geschäftsland<select name="country_code"><?php foreach($countries as $code=>$label):?><option value="<?=h($code)?>" <?=$code===$country?'selected':''?>><?=h(is_array($label)?($label['name']??$code):$label)?></option><?php endforeach;?></select></label><label class="field">Geschäftsadresse<textarea name="address_text" minlength="10" maxlength="500" required><?=h($values['address_text'])?></textarea></label><label class="field">Öffentliche Kontakt-E-Mail<input name="contact_email" type="email" maxlength="190" value="<?=h($values['contact_email'])?>" required></label><label class="field">Öffentliche Website<input name="website" type="url" maxlength="1000" value="<?=h($values['website'])?>" placeholder="https://..."></label><label class="field">Rechtliche Unternehmensangaben<textarea name="legal_notice" minlength="20" maxlength="10000" required><?=h($values['legal_notice'])?></textarea></label><p>Änderungen setzen das Profil erneut auf „Prüfung ausstehend“. Bereits laufende Banner werden bis zur erneuten Inhaltsfreigabe nicht ausgespielt.</p><button class="button" type="submit">Geschäftsangaben zur Prüfung speichern</button></form></section>
<section class="panel"><h2>Banner einreichen</h2><?php if(!$profile||$profile['status']!=='published'):?><p>Nach Freigabe deines Händlerprofils kannst du ein Banner zur Prüfung einreichen.</p><?php else:?><form method="post" enctype="multipart/form-data" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="campaign"><label class="field">Titel<input name="title" minlength="5" maxlength="120" required></label><label class="field">Zieladresse<input name="target_url" type="url" maxlength="1000" required placeholder="https://..."></label><label class="field">Zielmarkt<select name="country_code"><?php foreach($countries as $code=>$label):?><option value="<?=h($code)?>" <?=$code===$country?'selected':''?>><?=h(is_array($label)?($label['name']??$code):$label)?></option><?php endforeach;?></select></label><label class="field">Kategorie<select name="category_id"><?php foreach($categories as $category):?><option value="<?=(int)$category['id']?>"><?=h($category['name'])?></option><?php endforeach;?></select></label><label class="field">Bannerbild<input type="file" name="banner[]" accept="image/jpeg,image/png,image/webp" required><small>Genau ein Bild, höchstens 5 MiB und 20 Megapixel. Es wird sicher als WebP neu codiert.</small></label><button class="button" type="submit">Banner zur Inhaltsprüfung speichern</button></form><?php endif;?></section>
<section class="panel"><h2>Deine Kampagnen</h2><?php if(!$campaigns):?><p>Noch keine Kampagnen.</p><?php else:?><div class="cards"><?php foreach($campaigns as $campaign):?><article class="panel"><img src="?banner_image=<?=(int)$campaign['id']?>" alt="Vorschau deiner Kampagne" width="400" height="180" loading="lazy" style="max-height:180px;object-fit:contain"><h3><?=h($campaign['title'])?></h3><p><?=h($campaign['country_code'].' · '.business_state_label($campaign['status']))?></p><p><?=(int)$campaign['impressions']?> ausgelieferte Impressionen · <?=(int)$campaign['clicks']?> gezählte Klicks</p><p class="muted">Stündlich dedupliziert; keine Aussage über eindeutige Personen oder garantierte Reichweite.</p><?php if($campaign['moderation_reason']):?><p><?=h($campaign['moderation_reason'])?></p><?php endif;?></article><?php endforeach;?></div><?php endif;?></section>
<section class="panel"><h2>Angebote gesammelt verwalten</h2><form method="post" id="bulk-listings"><?=csrf_field()?><input type="hidden" name="action" value="bulk"><div class="table-wrap"><table class="data-table"><thead><tr><th>Auswahl</th><th>Angebot</th><th>Markt</th><th>Status</th></tr></thead><tbody><?php foreach($listings as $listing):$eligible=in_array($listing['status'],['draft','active','paused'],true)&&!(int)$listing['has_bids']&& !($listing['type']==='auction'&&$listing['status']==='active'&&market_expired($listing));?><tr><td><input type="checkbox" name="listing_ids[]" value="<?=(int)$listing['id']?>" aria-label="<?=h('Inserat '.$listing['id'].' auswählen')?>" <?=$eligible?'':'disabled'?>></td><td><?=h($listing['title'])?><br><small>#<?=(int)$listing['id']?></small></td><td><?=h($listing['country_code'])?></td><td><?=h($listing['status'])?></td></tr><?php endforeach;?></tbody></table></div><label class="field">Aktion<select name="transition"><option value="pause">Aktive Angebote pausieren</option><option value="archive">Angebote archivieren</option></select></label><p>Auktionen mit Geboten oder abgelaufener Frist sind geschützt. Sobald ein ausgewähltes Angebot unzulässig ist, wird die ganze Sammeländerung abgewiesen.</p><button class="button" type="submit">Ausgewählte Angebote ändern</button></form><nav class="pagination" aria-label="Angebotsseiten"><?php if($page>1):?><a href="?page=<?=$page-1?>">Zurück</a><?php endif;?><span>Seite <?=$page?> von <?=max(1,(int)ceil($total/25))?></span><?php if($page*25<$total):?><a href="?page=<?=$page+1?>">Weiter</a><?php endif;?></nav></section>
<section class="panel"><h2>CSV-Import & Export</h2><p>Import: UTF-8, Komma als Trenner, höchstens 100 neue Datensätze und 1 MiB pro Datei. Die Kopfzeile lautet:</p><pre style="overflow:auto">title,description,category_slug,type,price,buyout_price,duration_days,country_code,zip,city,condition_label,pickup,shipping</pre><p>Preise als Euro-Dezimaltext, Kategorien über ihre Kennung, type fixed oder auction, Zustand new/like_new/used, pickup/shipping 0 oder 1. Jede Zeile durchläuft die normale serverseitige Inseratsprüfung. Exakte vorhandene Artikel werden als Dublette gemeldet. Teilerfolge und Fehler werden zeilenweise angezeigt.</p>
<form method="post" enctype="multipart/form-data" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="import"><label class="field">CSV-Datei<input type="file" name="csv" accept="text/csv,.csv" required></label><label><input type="checkbox" name="accept_rules" value="1" required> Ich bestätige die allgemeinen Produktregeln und meine Berechtigung für sämtliche importierten Angebote.</label><button class="button" type="submit">CSV prüfen und gültige neue Angebote anlegen</button></form>
<?php if($report&&$report['errors']):?><div class="table-wrap"><table><thead><tr><th>CSV-Zeile</th><th>Fehler</th></tr></thead><tbody><?php foreach($report['errors'] as $row):?><tr><td><?=(int)$row['row']?></td><td><?=h($row['message'])?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?>
<form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="export"><label class="field">Export ab Inserats-ID <small>0 beginnt von vorn; maximal 1000 Datensätze pro Datei. Für den nächsten Teil die letzte exportierte ID einsetzen.</small><input name="after_id" inputmode="numeric" value="0" pattern="[0-9]+" required></label><button class="button secondary" type="submit">Eigene Angebote als CSV herunterladen</button></form><p>Die Exportdatei enthält zusätzliche ID-/Statusspalten und dient als Datenbericht. Vor einem Neuimport müssen Kopfzeile und Spalten an die Importvorlage angepasst werden. Tabellenformeln werden beim Export entschärft.</p></section></main>
<?php include __DIR__.'/../includes/footer.php';?>
